package com.citacloud.springboot.contacloud.app.views.components;

import com.citacloud.springboot.contacloud.app.dto.*;
import com.citacloud.springboot.contacloud.app.errors.UiErrorHandler;
import com.citacloud.springboot.contacloud.app.models.*;
import com.citacloud.springboot.contacloud.app.services.CierreCajaService;
import com.vaadin.flow.component.*;
import com.vaadin.flow.component.confirmdialog.ConfirmDialog;
import com.vaadin.flow.component.dialog.Dialog;
import com.vaadin.flow.component.grid.*;
import com.vaadin.flow.component.html.*;
import com.vaadin.flow.component.orderedlayout.*;
import com.vaadin.flow.component.textfield.*;
import java.math.BigDecimal;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.function.Consumer;

/** Cierre ciego: el esperado y la diferencia solo se presentan después del cierre confirmado. */
public final class CierreCajaDialog extends Dialog {
 private static final DateTimeFormatter DT=DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm");
 private final UUID sesionId; private final CierreCajaService service; private final Consumer<CierreCajaDto> terminado; private final Consumer<UUID> imprimir;
 private final Map<UUID,IntegerField> cantidades=new LinkedHashMap<>(); private final Span total=new Span();
 private PreparacionCierreCajaDto preparacion; private TextArea observacion; private AppActionButton confirmar;
 private UUID idempotencia=UUID.randomUUID(); private boolean enviando;
 public CierreCajaDialog(UUID sesionId,CierreCajaService service,Consumer<CierreCajaDto> terminado,Consumer<UUID> imprimir){this.sesionId=sesionId;this.service=service;this.terminado=terminado;this.imprimir=imprimir;setHeaderTitle("CERRAR CAJA");setWidth("min(780px,96vw)");setMaxHeight("92vh");addClassName("cc-cash-count-dialog");addOpenedChangeListener(e->{if(e.isOpened()&&preparacion==null)cargar();});}
 private void cargar(){try{preparacion=service.preparar(sesionId);formulario();}catch(RuntimeException ex){UiErrorHandler.show(ex,"No fue posible preparar el cierre de caja.");close();}}
 private void formulario(){removeAll();getFooter().removeAll();cantidades.clear();Div cab=new Div(new H3(preparacion.caja()+" · "+preparacion.sucursal()),new Span("● Abierta"));cab.addClassName("cc-cash-count-heading");HorizontalLayout info=new HorizontalLayout(info("Turno",preparacion.turno()),info("Apertura",DT.format(preparacion.apertura())),info("Cajero",preparacion.usuario()),info("Moneda",preparacion.monedaCodigo()));info.setWidthFull();VerticalLayout cuerpo=new VerticalLayout();cuerpo.setPadding(false);cuerpo.setSpacing(false);cuerpo.add(new H4("CONTEO FÍSICO CIEGO"),new Paragraph("Registra únicamente las cantidades físicas. El sistema mostrará el resultado después de confirmar el cierre."));TipoDenominacionCaja anterior=null;for(var d:preparacion.denominaciones()){if(d.tipo()!=anterior){Span grupo=new Span(d.tipo()==TipoDenominacionCaja.BANKNOTE?"BILLETES":"MONEDAS");grupo.addClassName("cc-cash-count-group");cuerpo.add(grupo);anterior=d.tipo();}IntegerField cantidad=new IntegerField();cantidad.setMin(0);cantidad.setMax(1_000_000);cantidad.setPlaceholder("0");cantidad.setWidth("120px");Span subtotal=new Span("0.00");subtotal.addClassName("cc-cash-count-money");cantidad.addValueChangeListener(e->{int q=Optional.ofNullable(e.getValue()).orElse(0);subtotal.setText(money(d.valor().multiply(BigDecimal.valueOf(q))));actualizarTotal();});cantidades.put(d.id(),cantidad);HorizontalLayout fila=new HorizontalLayout(new Span(preparacion.monedaSimbolo()+" "+money(d.valor())),cantidad,subtotal);fila.addClassName("cc-cash-count-row");fila.setWidthFull();fila.setFlexGrow(1,fila.getComponentAt(0));cuerpo.add(fila);}total.setText(preparacion.monedaCodigo()+" 0.00");Div totalBox=new Div(new Span("TOTAL CONTADO"),total);totalBox.addClassName("cc-cash-count-total");observacion=new TextArea("Observación");observacion.setMaxLength(500);observacion.setWidthFull();add(cab,info,cuerpo,totalBox,observacion);confirmar=new AppActionButton(ActionType.CLOSE_CASH,ButtonSize.MAIN,"Confirmar cierre",e->pedirConfirmacion());getFooter().add(confirmar,new AppActionButton(ActionType.CANCEL,ButtonSize.MAIN,"Cancelar",e->close()));}
 private void actualizarTotal(){BigDecimal t=BigDecimal.ZERO;for(var d:preparacion.denominaciones()){int q=Optional.ofNullable(cantidades.get(d.id()).getValue()).orElse(0);t=t.add(d.valor().multiply(BigDecimal.valueOf(q)));}total.setText(preparacion.monedaCodigo()+" "+money(t));}
 private void pedirConfirmacion(){if(enviando)return;ConfirmDialog d=new ConfirmDialog();d.setHeader("Confirmar cierre de caja");d.setText("Efectivo contado: "+total.getText()+". Después de cerrar el turno no podrá modificar el conteo.");d.setCancelable(true);d.setCancelText("Volver al conteo");d.setConfirmText("Cerrar caja");d.addConfirmListener(e->confirmar());d.open();}
 private void confirmar(){if(enviando)return;enviando=true;confirmar.setEnabled(false);try{List<ConfirmarCierreCajaInput.Cantidad> lineas=cantidades.entrySet().stream().map(x->new ConfirmarCierreCajaInput.Cantidad(x.getKey(),Optional.ofNullable(x.getValue().getValue()).orElse(0))).toList();CierreCajaDto cierre=service.confirmar(new ConfirmarCierreCajaInput(sesionId,idempotencia,lineas,observacion.getValue()));resultado(cierre);if(terminado!=null)terminado.accept(cierre);}catch(RuntimeException ex){enviando=false;confirmar.setEnabled(true);UiErrorHandler.show(ex,"No fue posible cerrar la caja.");if(ex.getMessage()!=null&&ex.getMessage().contains("observación"))observacion.focus();}}
 private void resultado(CierreCajaDto r){removeAll();getFooter().removeAll();setHeaderTitle("RESULTADO DEL CIERRE");Div generales=new Div(info("Número",r.numero()),info("Turno",r.turno()),info("Caja",r.caja()+" · "+r.sucursal()),info("Apertura",DT.format(r.apertura())),info("Cierre",DT.format(r.cierre())),info("Cajero",r.cerradoPor()),info("Moneda",r.monedaCodigo()));generales.addClassName("cc-cash-count-result-grid");Div estado=new Div(new H3(label(r.resultado())));estado.addClassNames("cc-cash-count-result","cc-result-"+r.resultado().name().toLowerCase());Div resumen=new Div(new H4("RESULTADO"),fila("Fondo inicial",amount(r,r.fondoInicial())),fila("Entradas en efectivo",amount(r,r.totalEntradasEfectivo())),fila("Salidas en efectivo",amount(r,r.totalSalidasEfectivo())),fila("Efectivo esperado",amount(r,r.esperado())),fila("Efectivo contado",amount(r,r.contado())),fila("Diferencia",signed(r,r.diferencia())),estado);resumen.addClassName("cc-cash-count-result-summary");VerticalLayout contenido=new VerticalLayout(generales,resumen);contenido.setPadding(false);contenido.setSpacing(false);Grid<CierreCajaDto.Detalle> grid=new Grid<>();grid.addColumn(x->r.monedaSimbolo()+" "+money(x.denominacion())).setHeader("Denominación");grid.addColumn(CierreCajaDto.Detalle::cantidad).setHeader("Cantidad").setTextAlign(ColumnTextAlign.END);grid.addColumn(x->money(x.subtotal())).setHeader("Subtotal").setTextAlign(ColumnTextAlign.END);grid.setItems(r.detalles());grid.setAllRowsVisible(true);contenido.add(new H4("CONTEO FÍSICO"),grid);if(r.observacion()!=null)contenido.add(info("Observación",r.observacion()));add(contenido);if(imprimir!=null)getFooter().add(new AppActionButton(ActionType.PRINT,ButtonSize.MAIN,"Imprimir cierre",e->imprimir.accept(r.id())));getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->close()));}
 private static Div info(String l,String v){Div d=new Div(new Span(l),new Span(v==null?"—":v));d.addClassName("cc-cash-count-info");return d;} private static Div fila(String l,String v){Div d=new Div(new Span(l),new Span(v));d.addClassName("cc-cash-count-result-row");return d;} private static String money(BigDecimal v){return PosNumberFormatter.money(v);} private static String amount(CierreCajaDto r,BigDecimal v){return r.monedaCodigo()+" "+money(v);} private static String signed(CierreCajaDto r,BigDecimal v){return r.monedaCodigo()+" "+(v.signum()>0?"+":"")+money(v);} private static String label(ResultadoRecuentoCaja r){return switch(r){case BALANCED->"CUADRE CORRECTO";case OVERAGE->"SOBRANTE DE CAJA";case SHORTAGE->"FALTANTE DE CAJA";};}
}
